/** Encode / decode any schema struct or union as a standalone message. */
export interface Codec<V> { encode(v: V): Uint8Array; decode(bytes: Uint8Array): V; }

const shared = new Writer(1024);
function mk<V>(enc: (w: Writer, v: V) => void, dec: (r: Reader, end: number) => V): Codec<V> {
  return {
    encode(v: V): Uint8Array { shared.reset(); enc(shared, v); return shared.finish(); },
    decode(bytes: Uint8Array): V { const r = new Reader(bytes); return dec(r, bytes.length); },
  };
}

