export type CodecName = keyof typeof codecs;

/** Encode into a caller-owned writer (no copy); the transport frames it. */
export function encodeEngineMessageInto(w: Writer, v: T.EngineMessage): void { encU_EngineMessage(w, v); }
export const encodeEngineMessage = (v: T.EngineMessage): Uint8Array => codecs.EngineMessage.encode(v);
export const decodeEngineMessage = (bytes: Uint8Array): T.EngineMessage => codecs.EngineMessage.decode(bytes);
